/* minimal jQuery counterUp (waypoints-triggered) */
(function($){$.fn.counterUp=function(o){var s=$.extend({time:2000,delay:10},o);return this.each(function(){var $t=$(this),n=$t.text().trim(),num=parseInt(n.replace(/[^0-9]/g,''),10);if(isNaN(num))return;var run=function(){if($t.data('cu-done'))return;$t.data('cu-done',1);var steps=Math.max(1,Math.round(s.time/s.delay)),i=0;var tm=setInterval(function(){i++;$t.text(Math.round(num*i/steps));if(i>=steps){clearInterval(tm);$t.text(n);}},s.delay);};if($.fn.waypoint){$t.waypoint(function(){run();this.destroy&&this.destroy();},{offset:'100%'});}else run();});};})(jQuery);
